from pathlib import Path
from datetime import datetime
import re, shutil

ROOT = Path(__file__).resolve().parent
BACKEND = ROOT / "backend" / "app.py"
STAMP = datetime.now().strftime("%Y%m%d_%H%M%S")
START = "# ===== MEALORA WEEKLY PLANNER V2 START ====="
END = "# ===== MEALORA WEEKLY PLANNER V2 END ====="

WEEKLY_ROUTE = '\n# ===== MEALORA WEEKLY PLANNER V2 START =====\n@app.route("/api/weekly-plan", methods=["POST"])\ndef weekly_plan_v2():\n    try:\n        import random\n        from collections import Counter\n        import numpy as np\n        import pandas as pd\n\n        data = request.get_json() or {}\n        pantry = data.get("pantry") or []\n        household = data.get("household") or {}\n        adults = max(int(household.get("adults", 0) or 0), 0)\n        children = max(int(household.get("children", 0) or 0), 0)\n        seniors = max(int(household.get("seniors", 0) or 0), 0)\n        if adults + children + seniors <= 0:\n            return jsonify({"success": False, "error": "Add at least one household member."}), 400\n\n        mode = str(data.get("mode", "automatic")).lower()\n        diet = str(data.get("diet", "Mixed") or "Mixed")\n        cuisine = str(data.get("cuisine", "Auto") or "Auto")\n        max_time = float(data.get("max_time", 45) or 45)\n        include_snacks = bool(data.get("include_snacks", True))\n        special_day = str(data.get("special_day", "Saturday") or "None")\n\n        ctx = build_context({\n            "mode": mode,\n            "date": data.get("date"),\n            "time": data.get("time"),\n            "location_city": data.get("location_city"),\n            "location": data.get("location_city"),\n            "latitude": data.get("latitude"),\n            "longitude": data.get("longitude"),\n            "meal_type": data.get("meal_type", "Automatic"),\n            "diet": diet,\n            "cuisine": cuisine,\n            "max_time": max_time,\n        })\n        if diet.lower() in ("auto", "automatic"):\n            diet = ctx["diet"]\n        if cuisine.lower() in ("auto", "automatic"):\n            cuisine = ctx["cuisine"]\n\n        def norm(v):\n            import re as _re\n            return _re.sub(r"[^a-z0-9\\s]+", " ", str(v or "").lower()).strip()\n\n        def tok(v):\n            return {x for x in norm(v).split() if len(x) > 2}\n\n        def lines(v):\n            if isinstance(v, list):\n                return [str(x).strip() for x in v if str(x).strip()]\n            s = str(v or "").strip()\n            if not s or s.lower() == "nan":\n                return []\n            if s.startswith("[") and s.endswith("]"):\n                try:\n                    q = json.loads(s)\n                    if isinstance(q, list):\n                        return [str(x).strip() for x in q if str(x).strip()]\n                except Exception:\n                    pass\n            q = [x.strip(" •\\t") for x in s.replace("\\r", "\\n").split("\\n") if x.strip()]\n            if len(q) > 1:\n                return q\n            return [x.strip() for x in s.split(";") if x.strip()] if ";" in s else [s]\n\n        pantry_names = []\n        expiring = []\n        today = now_india().date()\n        for item in pantry:\n            name = item.get("normalized_name") or item.get("ingredient_name") or item.get("name")\n            if name:\n                pantry_names.append(norm(name))\n            expiry = item.get("expiry_date")\n            if name and expiry:\n                try:\n                    if (datetime.strptime(str(expiry)[:10], "%Y-%m-%d").date() - today).days <= 7:\n                        expiring.append(norm(name))\n                except Exception:\n                    pass\n\n        pantry_tokens = set().union(*(tok(x) for x in pantry_names)) if pantry_names else set()\n        expiry_tokens = set().union(*(tok(x) for x in expiring)) if expiring else set()\n\n        def num(row, names, default=0.5):\n            for name in names:\n                if name in row.index:\n                    try:\n                        x = float(row.get(name))\n                        if np.isfinite(x):\n                            return float(np.clip(x, 0, 1))\n                    except Exception:\n                        pass\n            return default\n\n        def enrich(df):\n            if df is None or df.empty:\n                return pd.DataFrame()\n            df = df.copy()\n            if "recipe_id" not in df.columns:\n                df["recipe_id"] = [str(i) for i in range(len(df))]\n            if "recipe_name" not in df.columns:\n                df["recipe_name"] = df.get("name", df.get("title", "Mealora Recipe"))\n            df["recipe_id"] = df["recipe_id"].astype(str)\n            df["recipe_name"] = df["recipe_name"].fillna("Mealora Recipe").astype(str)\n            df = df.drop_duplicates("recipe_id").reset_index(drop=True)\n\n            ing_col = next((c for c in ["ingredient_names","ingredients","Cleaned-Ingredients","cleaned_ingredients","TranslatedIngredients"] if c in df.columns), None)\n            vals = []\n            for _, row in df.iterrows():\n                ing = lines(row.get(ing_col, "")) if ing_col else []\n                it = tok(" ".join(ing))\n                matched = [p for p in pantry_names if tok(p) & it]\n                exp = [p for p in expiring if tok(p) & it]\n                direct = len(pantry_tokens & it) / max(len(it), 1)\n                pantry_score = np.clip(0.7 * (len(matched) / max(len(pantry_names), 1) if pantry_names else 0) + 0.3 * direct, 0, 1)\n                expiry_score = len(set().union(*(tok(x) for x in exp))) / max(len(expiry_tokens), 1) if expiry_tokens else 0\n                learned = max(num(row, ["rf_suitability_score","ml_suitability_score"], 0), num(row, ["han_score"], 0))\n                if learned == 0:\n                    learned = num(row, ["final_score","mealora_score"], 0.5)\n                vals.append({\n                    "ingredients": ing, "ingredient_tokens": it,\n                    "matched_pantry": matched,\n                    "suitability": learned, "pantry": float(pantry_score),\n                    "expiry": float(np.clip(expiry_score, 0, 1)),\n                    "context": num(row, ["context_score"], 0.5),\n                    "nutrition": num(row, ["nutrition_score"], 0.5),\n                    "purchase": float(np.clip(direct, 0, 1))\n                })\n            extra = pd.DataFrame(vals)\n            return pd.concat([df.reset_index(drop=True), extra], axis=1)\n\n        def get_pool(meal, n=30):\n            try:\n                result = recommend(\n                    reference_recipe="Balu shahi", target_user=1, top_k=n,\n                    meal_type=meal, diet=diet, cuisine=cuisine, max_time=max_time,\n                    weather=ctx["weather"], festival=ctx["festival"],\n                    location={"city":ctx["location_city"],"location_city":ctx["location_city"],\n                              "latitude":ctx["latitude"],"longitude":ctx["longitude"],\n                              "cuisine_hint":cuisine_hint(ctx["latitude"],ctx["longitude"])}\n                )\n            except TypeError:\n                result = recommend(reference_recipe="Balu shahi", target_user=1, top_k=n,\n                                   meal_type=meal, diet=diet, cuisine=cuisine, max_time=max_time)\n            return enrich(result)\n\n        pools = {m: get_pool(m, 35) for m in ["Breakfast","Lunch","Dinner"]}\n        available = [p for p in pools.values() if not p.empty]\n        if not available:\n            raise RuntimeError("No recipe candidates were returned by Mealora.")\n        fallback = max(available, key=len)\n        for m in pools:\n            if pools[m].empty:\n                pools[m] = fallback.copy()\n\n        treat_terms = ("biryani","biriyani","pulao","fried rice","korma","tikka","butter masala","special")\n        special_pool = pools["Dinner"][pools["Dinner"]["recipe_name"].str.lower().apply(lambda x:any(t in x for t in treat_terms))].copy()\n        if special_pool.empty:\n            special_pool = pools["Dinner"].copy()\n\n        days = ["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"]\n        slot_types = ["breakfast","lunch_main","lunch_side","dinner_main","dinner_side"]\n        slots = [(d,s) for d in days for s in slot_types]\n\n        master = []\n        key_to_idx = {}\n        domains = []\n\n        def add(pool):\n            out = []\n            for _, row in pool.iterrows():\n                key = f"{row[\'recipe_id\']}::{row[\'recipe_name\']}"\n                if key not in key_to_idx:\n                    key_to_idx[key] = len(master)\n                    master.append(row.to_dict())\n                out.append(key_to_idx[key])\n            return list(dict.fromkeys(out))\n\n        for day, slot in slots:\n            if day == special_day and slot == "dinner_main" and special_day != "None":\n                domain = add(special_pool)\n            elif slot == "breakfast":\n                domain = add(pools["Breakfast"])\n            elif slot.startswith("lunch"):\n                domain = add(pools["Lunch"])\n            else:\n                domain = add(pools["Dinner"])\n            domains.append(domain or list(range(len(master))))\n\n        candidates = pd.DataFrame(master)\n\n        def fitness(ch):\n            rows = [candidates.iloc[i] for i in ch]\n            ingredient_sets = [set(r.get("ingredient_tokens", set())) for r in rows]\n            counts = Counter(x for s in ingredient_sets for x in s)\n            reuse = np.mean([min(counts[x]/3,1) for x in counts]) if counts else 0\n            unique = len(set(ch))/len(ch)\n            nutrition = np.array([float(r.get("nutrition",.5)) for r in rows])\n            nutrition_score = .75*nutrition.mean() + .25*np.clip(1-nutrition.std(),0,1)\n            return np.array([\n                np.mean([r.get("suitability",.5) for r in rows]),\n                np.mean([r.get("pantry",0) for r in rows]),\n                np.mean([r.get("expiry",0) for r in rows]),\n                nutrition_score,\n                np.mean([r.get("context",.5) for r in rows]),\n                np.mean([r.get("purchase",.5) for r in rows]),\n                reuse, unique, unique\n            ], dtype=float)\n\n        def dominates(a,b):\n            return np.all(a>=b) and np.any(a>b)\n\n        def fronts(pop, vals):\n            fs=[[]]; dc=[0]*len(pop); ds=[[] for _ in pop]\n            for i in range(len(pop)):\n                for j in range(len(pop)):\n                    if i==j: continue\n                    if dominates(vals[i],vals[j]): ds[i].append(j)\n                    elif dominates(vals[j],vals[i]): dc[i]+=1\n                if dc[i]==0: fs[0].append(i)\n            k=0\n            while k<len(fs) and fs[k]:\n                nxt=[]\n                for i in fs[k]:\n                    for j in ds[i]:\n                        dc[j]-=1\n                        if dc[j]==0: nxt.append(j)\n                if nxt: fs.append(nxt)\n                k+=1\n            return fs\n\n        def crowd(front, vals):\n            d={i:0.0 for i in front}\n            if len(front)<=2:\n                for i in front:d[i]=float("inf")\n                return d\n            for o in range(vals.shape[1]):\n                q=sorted(front,key=lambda i:vals[i,o])\n                d[q[0]]=d[q[-1]]=float("inf")\n                lo,hi=vals[q[0],o],vals[q[-1],o]\n                if hi==lo: continue\n                for k in range(1,len(q)-1):\n                    d[q[k]]+=(vals[q[k+1],o]-vals[q[k-1],o])/(hi-lo)\n            return d\n\n        def mutate(ch):\n            ch=ch[:]\n            for i in range(len(ch)):\n                if random.random()<.18: ch[i]=random.choice(domains[i])\n            return ch\n\n        random.seed(42); np.random.seed(42)\n        pop_size, generations = 60, 40\n        population=[[random.choice(d) for d in domains] for _ in range(pop_size)]\n\n        best_front=None; best_vals=None\n        for _ in range(generations):\n            vals=np.array([fitness(x) for x in population])\n            fs=fronts(population,vals)\n            if fs and fs[0]:\n                best_front=[population[i][:] for i in fs[0]]\n                best_vals=vals[fs[0]]\n            ranks=np.zeros(len(population),dtype=int); cd=np.zeros(len(population))\n            for rank,f in enumerate(fs):\n                for i in f:ranks[i]=rank\n                for i,v in crowd(f,vals).items():cd[i]=v\n            offspring=[]\n            while len(offspring)<pop_size:\n                def pick():\n                    a,b=random.randrange(pop_size),random.randrange(pop_size)\n                    if ranks[a]<ranks[b] or (ranks[a]==ranks[b] and cd[a]>cd[b]): return population[a][:]\n                    return population[b][:]\n                a,b=pick(),pick()\n                cut=random.randint(1,len(a)-1)\n                c1=mutate(a[:cut]+b[cut:]); c2=mutate(b[:cut]+a[cut:])\n                offspring.extend([c1,c2])\n            combined=population+offspring[:pop_size]\n            cv=np.array([fitness(x) for x in combined])\n            fs=fronts(combined,cv); new=[]\n            for f in fs:\n                if len(new)+len(f)<=pop_size:\n                    new.extend(combined[i] for i in f)\n                else:\n                    ordered=sorted(f,key=lambda i:crowd(f,cv)[i],reverse=True)\n                    new.extend(combined[i] for i in ordered[:pop_size-len(new)])\n                    break\n            population=new\n\n        if not best_front:\n            raise RuntimeError("NSGA-II did not produce a weekly plan.")\n\n        weights=np.array([.25,.15,.12,.12,.10,.08,.08,.06,.04])\n        selected=best_front[int(np.argmax([np.dot(np.clip(v,0,1),weights) for v in best_vals]))]\n\n        def serial(i, treat=False):\n            r=candidates.iloc[int(i)]\n            return {\n                "recipe_id":str(r.get("recipe_id","")),\n                "recipe_name":str(r.get("recipe_name","Mealora Recipe")),\n                "suitability_score":round(float(r.get("suitability",.5)),4),\n                "pantry_score":round(float(r.get("pantry",0)),4),\n                "expiry_score":round(float(r.get("expiry",0)),4),\n                "context_score":round(float(r.get("context",.5)),4),\n                "nutrition_score":round(float(r.get("nutrition",.5)),4),\n                "purchase_score":round(float(r.get("purchase",.5)),4),\n                "matched_pantry":list(r.get("matched_pantry",[]))[:12],\n                "ingredients":list(r.get("ingredients",[])),\n                "is_treat":treat\n            }\n\n        plan=[]\n        for di,day in enumerate(days):\n            b=di*5\n            is_special=special_day!="None" and day==special_day\n            vals={"day":day,\n                  "theme":"Weekend special / treat meal" if is_special else "Balanced pantry-aware day",\n                  "is_special_day":is_special,\n                  "breakfast":serial(selected[b]),\n                  "lunch_main":serial(selected[b+1]),\n                  "lunch_side":serial(selected[b+2]),\n                  "dinner_main":serial(selected[b+3],is_special),\n                  "dinner_side":serial(selected[b+4],is_special)}\n            if vals["lunch_side"]["recipe_id"]==vals["lunch_main"]["recipe_id"]:\n                for x in domains[b+2]:\n                    if str(candidates.iloc[x]["recipe_id"])!=vals["lunch_main"]["recipe_id"]:\n                        vals["lunch_side"]=serial(x); break\n            if vals["dinner_side"]["recipe_id"]==vals["dinner_main"]["recipe_id"]:\n                for x in domains[b+4]:\n                    if str(candidates.iloc[x]["recipe_id"])!=vals["dinner_main"]["recipe_id"]:\n                        vals["dinner_side"]=serial(x,is_special); break\n            plan.append(vals)\n\n        if include_snacks:\n            try: snack=get_pool("Snack",20)\n            except Exception: snack=pd.DataFrame()\n            if snack.empty: snack=pools["Breakfast"].copy()\n            snack["_score"]=(.45*snack["suitability"]+.25*snack["pantry"]+.15*snack["expiry"]+.10*snack["context"]+.05*snack["purchase"])\n            snack=snack.sort_values("_score",ascending=False).drop_duplicates("recipe_id").reset_index(drop=True)\n            for i,day in enumerate(plan):\n                if len(snack):\n                    r=snack.iloc[i%len(snack)]\n                    day["snack"]=serial(r.name if r.name < len(candidates) else 0) if False else {\n                        "recipe_id":str(r.get("recipe_id","")),\n                        "recipe_name":str(r.get("recipe_name","Light snack")),\n                        "suitability_score":round(float(r.get("suitability",.5)),4),\n                        "pantry_score":round(float(r.get("pantry",0)),4),\n                        "expiry_score":round(float(r.get("expiry",0)),4),\n                        "context_score":round(float(r.get("context",.5)),4),\n                        "nutrition_score":round(float(r.get("nutrition",.5)),4),\n                        "purchase_score":round(float(r.get("purchase",.5)),4),\n                        "matched_pantry":list(r.get("matched_pantry",[]))[:12],\n                        "is_treat":False\n                    }\n\n        all_rec=[d[k] for d in plan for k in ("breakfast","lunch_main","lunch_side","dinner_main","dinner_side","snack") if d.get(k)]\n        unique=len({x["recipe_id"] for x in all_rec})\n        def avg(k,default=.5): return float(np.mean([x.get(k,default) for x in all_rec])) if all_rec else default\n\n        return jsonify({\n            "success":True, "context":ctx, "plan":plan,\n            "summary":{\n                "meals_planned":len(all_rec),\n                "unique_recipes":unique,\n                "pantry_utilization":round(avg("pantry",0)*100,1),\n                "expiry_utilization":round(avg("expiry",0)*100,1),\n                "nutrition_score":round(avg("nutrition_score")*100,1),\n                "context_score":round(avg("context_score")*100,1),\n                "purchase_burden":round((1-avg("purchase_score"))*100,1),\n                "algorithm":"RF + HAN candidate scoring + NSGA-II multi-objective optimization",\n                "optimizer_generations":generations,\n                "optimizer_population":pop_size,\n                "planning_horizon":"7 days",\n                "objectives":["learned suitability","pantry coverage","expiry utilization","nutrition","context","purchase burden","ingredient reuse","variety","uniqueness"]\n            }\n        })\n    except Exception as e:\n        import traceback; traceback.print_exc()\n        return jsonify({"success":False,"error":str(e)}),500\n\n# ===== MEALORA WEEKLY PLANNER V2 END =====\n'

source = BACKEND.read_text(encoding="utf-8")
backup = BACKEND.with_name(BACKEND.name + f".before_weekly_v2_{STAMP}")
shutil.copy2(BACKEND, backup)

# Remove our previous version if it exists.
source = re.sub(re.escape(START) + r".*?" + re.escape(END), "", source, flags=re.S)

# Remove an older unmarked /api/weekly-plan route if present.
source = re.sub(
    r'@app\.route\("/api/weekly-plan".*?(?=@app\.route\(|if __name__ == "__main__":)',
    "",
    source,
    flags=re.S,
)

# The route uses build_context and recommend, which already exist in app.py.
anchor = '@app.route("/api/recipe-assistant", methods=["POST"])'
if anchor not in source:
    anchor = 'if __name__ == "__main__":'

if anchor not in source:
    raise SystemExit("Could not find a safe insertion point in backend/app.py.")

source = source.replace(anchor, WEEKLY_ROUTE.strip() + "\n\n" + anchor, 1)

if "\nimport re\n" not in source:
    source = source.replace("import json\n", "import json\nimport re\n", 1)

BACKEND.write_text(source, encoding="utf-8")

print("Mealora Weekly Planner V2 installed.")
print("Updated:", BACKEND)
print("Backup :", backup)
